  values (l_id, 'HEADER', q'~select nvl(:INVOICE_NO, 'INV-2026-0042')        as inv_no,
       trunc(sysdate)                            as inv_date,
       trunc(sysdate) + 30                       as due_date,
       'Net 30 days'                             as terms,
       'Ceylon Hardware Stores'                  as customer,
       'No. 25, Inner Harbour Road' || chr(10) ||
       'Trincomalee 31000, Sri Lanka'            as address,
       '+94 26 222 1234'                         as phone
  from dual~', q'~{"INVOICE_NO":"INV-2026-0042"}~', 10);
  insert into rpt_sources (report_id, name, sql_text, test_params, seq)
  values (l_id, 'LINES', q'~select line_no, category, description, qty, price, qty * price as amount
  from (select level as line_no,
               case when level <= 14 then 'Electrical'
                    when level <= 30 then 'Hardware'
                    else 'Paints' end as category,
               'Product P-' || lpad(level, 4, '0') ||
               case when mod(level, 6) = 0
                    then ' - heavy duty model with extended warranty, delivered and installed on site by our technicians'
               end as description,
               mod(level * 7, 9) + 1 as qty,
               round(250 + mod(level * 37, 50) * 95.5, 2) as price
          from dual connect by level <= 44)
 order by category, line_no~', q'~{}~', 20);
