  returning report_id into l_id;
  insert into rpt_sources (report_id, name, sql_text, test_params, seq)
  values (l_id, 'STOCK', q'~select level as item_no,
       'SKU-' || lpad(level * 13, 5, '0') as sku,
       initcap(decode(mod(level, 5), 0, 'cable roll', 1, 'paint tin', 2, 'hinge set', 3, 'led bulb', 'wall plug')) || ' ' || level as item_name,
       decode(mod(level, 3), 0, 'Colombo', 1, 'Trincomalee', 'Kandy') as store,
       mod(level * 17, 120) as on_hand,
       round(120 + mod(level * 29, 40) * 22.75, 2) as unit_cost,
       mod(level * 17, 120) * round(120 + mod(level * 29, 40) * 22.75, 2) as stock_value
